-- Migration 028: corrected SMA lesson checkpoint and try-it expansions.
-- Targets actual sma_* skill codes (migration 025 used wrong unprefixed codes,
-- so its SMA portion was a no-op; this migration delivers the SMA half).
-- Auto-generated by encode_sma_lesson_explanations.py.
BEGIN;

CREATE OR REPLACE FUNCTION public._patch_cp_sma2(
    p_skill_code TEXT,
    p_stem_fr TEXT,
    p_new_explanation TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_question_idx INT;
    v_block JSONB;
    v_questions JSONB;
    v_question JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
    v_n_questions INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'checkpoint' THEN CONTINUE; END IF;
            v_questions := v_block->'questions';
            IF v_questions IS NULL THEN CONTINUE; END IF;
            v_n_questions := jsonb_array_length(v_questions);
            FOR v_question_idx IN 0..(v_n_questions - 1) LOOP
                v_question := v_questions->v_question_idx;
                IF v_question->>'stem_fr' = p_stem_fr THEN
                    v_lesson := jsonb_set(
                        v_lesson,
                        ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'questions', v_question_idx::text, 'explanation_fr'],
                        to_jsonb(p_new_explanation)
                    );
                    v_found := TRUE;
                END IF;
            END LOOP;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public._patch_tryit_sma2(
    p_skill_code TEXT,
    p_problem_fr TEXT,
    p_new_hint TEXT,
    p_new_solution TEXT
) RETURNS BOOLEAN AS $$
DECLARE
    v_lesson JSONB;
    v_section_idx INT;
    v_block_idx INT;
    v_block JSONB;
    v_found BOOLEAN := FALSE;
    v_n_sections INT;
    v_n_blocks INT;
BEGIN
    SELECT lesson INTO v_lesson FROM public.skills WHERE code = p_skill_code;
    IF v_lesson IS NULL OR v_lesson->'sections' IS NULL THEN RETURN FALSE; END IF;
    v_n_sections := jsonb_array_length(v_lesson->'sections');
    FOR v_section_idx IN 0..(v_n_sections - 1) LOOP
        IF v_lesson->'sections'->v_section_idx->'blocks' IS NULL THEN CONTINUE; END IF;
        v_n_blocks := jsonb_array_length(v_lesson->'sections'->v_section_idx->'blocks');
        FOR v_block_idx IN 0..(v_n_blocks - 1) LOOP
            v_block := v_lesson->'sections'->v_section_idx->'blocks'->v_block_idx;
            IF v_block->>'kind' <> 'try_it' THEN CONTINUE; END IF;
            IF v_block->>'problem_fr' = p_problem_fr THEN
                v_lesson := jsonb_set(v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'hint_fr'],
                    to_jsonb(p_new_hint));
                v_lesson := jsonb_set(v_lesson,
                    ARRAY['sections', v_section_idx::text, 'blocks', v_block_idx::text, 'solution_fr'],
                    to_jsonb(p_new_solution));
                v_found := TRUE;
            END IF;
        END LOOP;
    END LOOP;
    IF v_found THEN
        UPDATE public.skills SET lesson = v_lesson WHERE code = p_skill_code;
    END IF;
    RETURN v_found;
END;
$$ LANGUAGE plpgsql;

SELECT public._patch_tryit_sma2('sma_limit_def', 'Détermine $\displaystyle\lim_{x\to 1} \dfrac{x^2 - 1}{x - 1}$.', 'Substitution directe en $x = 1$ : numérateur $1 - 1 = 0$, dénominateur $1 - 1 = 0$. **Forme indéterminée $\frac{0}{0}$** — signal qu''il faut factoriser. Pense à l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$.', 'Substitution directe en $x = 1$ : numérateur $1^2 - 1 = 0$, dénominateur $1 - 1 = 0$. **Forme indéterminée $\frac{0}{0}$** — c''est le signal qu''il faut factoriser. On utilise l''identité remarquable $a^2 - b^2 = (a-b)(a+b)$ avec $a = x, b = 1$ : $x^2 - 1 = (x-1)(x+1)$. La fraction se réécrit $\dfrac{(x-1)(x+1)}{x-1}$. Le facteur $(x-1)$ se simplifie au numérateur et au dénominateur — **légitime** parce qu''on étudie la limite *quand* $x \to 1$, donc avec $x \ne 1$. Il reste $\lim_{x \to 1}(x+1) = 2$. **Pattern à retenir** : forme $\frac{0}{0}$ ⇒ chercher une factorisation cachée.');
SELECT public._patch_tryit_sma2('sma_deriv_definition', 'Dérive $f(x) = (2x+1)^3$.', 'C''est une **composition** : applique la règle de dérivation des fonctions composées. Pose $v(x) = 2x + 1$ et utilise $(v^3)'' = 3 v^2 \cdot v''$ — n''oublie pas de multiplier par la dérivée de $v$.', 'On reconnaît une **composition** $f = u \circ v$ avec $v(x) = 2x + 1$ et $u(t) = t^3$. **Règle de la chaîne** : $f''(x) = u''(v(x)) \cdot v''(x)$. Calcul : $u''(t) = 3 t^2$, donc $u''(v(x)) = 3 (2x+1)^2$. Et $v''(x) = 2$. **Multiplication** : $f''(x) = 3 (2x+1)^2 \cdot 2 = 6 (2x+1)^2$. **Erreur classique** : oublier le $\times 2$ (la dérivée de l''argument intérieur) et écrire $f''(x) = 3(2x+1)^2$ — incorrect. La règle de la chaîne EXIGE de multiplier par $v''$.');
SELECT public._patch_tryit_sma2('sma_sequences_review', 'Soit $(v_n)$ définie par $v_0 = 4$ et $v_{n+1} = \frac{v_n}{2} + 1$. Trouve son point fixe.', 'Le **point fixe** $L$ d''une suite récurrente $v_{n+1} = f(v_n)$ vérifie $L = f(L)$. Pose donc $L = L/2 + 1$ et résous l''équation linéaire en $L$.', '**Méthode du point fixe** : si $(v_n)$ converge vers $L$ et que $f$ est continue, alors $L = f(L)$. Ici $f(v) = v/2 + 1$, donc on résout $L = L/2 + 1$. **Calcul** : $L - L/2 = 1$, soit $L/2 = 1$, donc $L = 2$. **Vérification** : $f(2) = 2/2 + 1 = 2$ ✓ — c''est bien un point fixe. **Note** : pour conclure que la suite converge vers 2, il faut encore montrer monotonie + bornes. Ici on peut prouver que $|v_{n+1} - 2| = |v_n - 2|/2$, donc l''écart au point fixe est divisé par 2 à chaque étape — convergence garantie.');
SELECT public._patch_tryit_sma2('sma_ph_definition', 'Pour l''acide nitreux $\text{HNO}_2/\text{NO}_2^-$ (pKa = 3,4), à pH = 4, quelle forme prédomine ?', 'Compare le pH de la solution au pKa du couple. **Règle** : si pH > pKa, la base prédomine ; si pH < pKa, l''acide prédomine. Quantitativement, le rapport $[\text{base}]/[\text{acide}] = 10^{\text{pH}-\text{pK}_a}$.', '**Règle de prédominance** : pH > pKa → la **base conjuguée** prédomine ; pH < pKa → l''acide prédomine. Ici pH = 4 et pKa = 3,4, donc **pH > pKa de 0,6 unité** : la base $\text{NO}_2^-$ prédomine. **Quantitativement** (Henderson-Hasselbalch) : $\log\dfrac{[\text{NO}_2^-]}{[\text{HNO}_2]} = \text{pH} - \text{pK}_a = 0{,}6$, donc le ratio $[\text{NO}_2^-]/[\text{HNO}_2] = 10^{0{,}6} \approx 4$. Il y a environ 4 fois plus de base que d''acide. **Cohérent** : à pH = pKa exactement, ratio = 1 (les deux formes égales) ; au-delà, la base domine progressivement.');

SELECT public._patch_cp_sma2('sma_am_basics', 'Si $m > 1$ :', 'Le coefficient de modulation $m = U_m/U_p$ (rapport amplitude signal modulant / porteuse) doit rester $\le 1$. Si $m > 1$ : **sur-modulation**, l''enveloppe du signal modulé croise zéro et la détection produit une distorsion irrécupérable. **Critère pratique** : régler la station d''émission pour $m \le 0{,}9$ idéalement.');
SELECT public._patch_cp_sma2('sma_am_basics', 'Pourquoi utiliser une porteuse haute fréquence ?', 'Les ondes audio (20 Hz–20 kHz) ne se propagent pas efficacement dans l''atmosphère et nécessiteraient des antennes gigantesques (longueur d''onde de plusieurs km). On les **transporte** sur une porteuse radio (kHz–MHz) qui se propage bien et permet des antennes de taille raisonnable. **Principe AM** : moduler l''amplitude de la porteuse par le signal audio.');
SELECT public._patch_cp_sma2('sma_am_basics', 'Amplitude d''un signal $s(t) = 5 \cos(100 t)$ :', 'Pour un signal sinusoïdal $s(t) = A \cos(\omega t + \varphi)$, l''amplitude est le **coefficient devant le cosinus**, soit $A$. Ici $A = 5$ (l''unité dépend du contexte : V, A, etc.). $\omega = 100$ rad/s est la pulsation, à ne pas confondre avec l''amplitude. **Mémo** : amplitude = hauteur max du signal.');
SELECT public._patch_cp_sma2('sma_am_basics', 'Le filtre passe-bas après détection d''enveloppe sert à :', 'Après détection d''enveloppe, le signal contient encore des résidus haute fréquence de la porteuse $f_c$. Le **filtre passe-bas** ne laisse passer que les composantes basses fréquences (le signal modulant $f_m$, audio) et **élimine $f_c$**. Le résultat est le signal audio reconstitué, prêt pour le haut-parleur.');
SELECT public._patch_cp_sma2('sma_b_field_basics', 'Sur un fil parcouru par $i$ dans $\vec{B}$, la force est :', 'La **force de Laplace** sur un élément de fil est $d\vec{F} = i\,d\vec{\ell} \wedge \vec{B}$. Le **produit vectoriel** rend $\vec{F}$ perpendiculaire à la fois au fil ($d\vec{\ell}$) et à $\vec{B}$. Sa norme est maximale quand le fil est perpendiculaire au champ ($\sin\theta = 1$). Application : moteur électrique, balance de Cotton.');
SELECT public._patch_cp_sma2('sma_b_field_basics', 'Si on double $v$, le rayon :', 'Pour une charge $q$ en mouvement circulaire dans $\vec{B}$, l''égalité $qvB = mv^2/r$ donne $r = mv/(qB)$ — donc **$r$ proportionnel à $v$**. Doubler la vitesse double le rayon de la trajectoire. La **fréquence cyclotron** $f = qB/(2\pi m)$ ne dépend pas de $v$, seul le rayon change.');
SELECT public._patch_cp_sma2('sma_b_field_basics', '$\vec{u} \wedge \vec{v} = \vec{0}$ si :', 'Le produit vectoriel s''annule ssi $\vec{u}$ et $\vec{v}$ sont **parallèles** (ou antiparallèles), c''est-à-dire colinéaires. Justification : $|\vec{u} \wedge \vec{v}| = |\vec{u}||\vec{v}|\sin\theta$, et $\sin\theta = 0$ ssi $\theta = 0$ ou $\pi$. **Cas particulier** : si l''un des vecteurs est nul, le produit est nul aussi.');
SELECT public._patch_cp_sma2('sma_b_field_basics', 'Si on double $B$, le rayon :', 'De $r = mv/(qB)$, on voit que **$r \propto 1/B$** : doubler $B$ **divise le rayon par deux**. Plus le champ magnétique est fort, plus la trajectoire circulaire est serrée. Application : un spectromètre de masse utilise un $B$ fort pour bien séparer des ions de masses voisines.');
SELECT public._patch_cp_sma2('sma_b_field_basics', 'Sur une charge en mouvement dans $\vec{B}$, le travail de la force magnétique est :', 'La force magnétique $\vec{F} = q\vec{v} \wedge \vec{B}$ est **toujours perpendiculaire à $\vec{v}$** (par le produit vectoriel). Le travail élémentaire $\vec{F} \cdot d\vec{r} = \vec{F} \cdot \vec{v}\,dt = 0$ — **toujours nul**. Conséquence : la force magnétique **ne change jamais l''énergie cinétique**, seulement la direction du mouvement.');
SELECT public._patch_cp_sma2('sma_b_field_basics', 'Une charge au repos dans $\vec{B}$ subit :', '$\vec{F} = q\vec{v} \wedge \vec{B}$ : si $\vec{v} = \vec{0}$, alors $\vec{F} = \vec{0}$. **Une charge immobile ne subit aucune force magnétique**, même dans un champ très fort. Contrairement à la force électrique qui agit sur toute charge, qu''elle bouge ou non.');
SELECT public._patch_cp_sma2('sma_complex_basics', 'Module de $3 + 4i$ :', '**Module** d''un complexe $z = a + bi$ : $|z| = \sqrt{a^2 + b^2}$ — distance à l''origine dans le plan complexe. Pour $3 + 4i$ : $|z| = \sqrt{9 + 16} = \sqrt{25} = 5$. **Astuce** : reconnaître le triplet pythagoricien $(3, 4, 5)$, très courant dans les exercices — mémoriser fait gagner du temps.');
SELECT public._patch_cp_sma2('sma_complex_basics', '$|e^{i\theta}|$ vaut :', '$e^{i\theta} = \cos\theta + i\sin\theta$, donc $|e^{i\theta}| = \sqrt{\cos^2\theta + \sin^2\theta} = \sqrt{1} = 1$. Géométriquement : $e^{i\theta}$ parcourt le **cercle unité** quand $\theta$ varie. C''est la base de la forme exponentielle des complexes : $z = re^{i\theta}$ avec $r = |z|$.');
SELECT public._patch_cp_sma2('sma_complex_basics', 'Distance entre $z_1 = 1+i$ et $z_2 = 4+5i$ :', 'La distance entre les points d''affixes $z_1$ et $z_2$ est $|z_2 - z_1|$. Calcul : $z_2 - z_1 = (4-1) + (5-1)i = 3 + 4i$. Donc $|z_2 - z_1| = \sqrt{9 + 16} = 5$. **Astuce** : le triplet $(3, 4, 5)$ revient encore — on le retrouve souvent en géométrie complexe.');
SELECT public._patch_cp_sma2('sma_complex_basics', '$\cos(\pi/2) = ?$', '$\cos(\pi/2) = 0$. Valeur fondamentale du cercle trigonométrique : à l''angle $\pi/2$ (= 90°), le point sur le cercle unité est en haut (axe Oy), donc abscisse = $\cos(\pi/2) = 0$. **Mémo** : $\cos$ s''annule en $\pi/2 + k\pi$ pour $k$ entier.');
SELECT public._patch_cp_sma2('sma_complex_basics', '$\sin(\pi) = ?$', '$\sin(\pi) = 0$. À l''angle $\pi$ (= 180°), le point sur le cercle unité est en $(-1, 0)$, donc ordonnée = $\sin(\pi) = 0$. **Mémo** : $\sin$ s''annule en $k\pi$ pour $k$ entier — autres zéros : 0, $\pi$, $2\pi$, etc.');
SELECT public._patch_cp_sma2('sma_complex_basics', '$i^2 = ?$', 'Par **définition** du nombre $i$ (unité imaginaire) : $i^2 = -1$. C''est cette propriété qui distingue $\mathbb{C}$ de $\mathbb{R}$ — dans $\mathbb{R}$, aucun carré n''est négatif. **Conséquences** : $i^3 = -i$, $i^4 = 1$, et les puissances de $i$ cyclent par 4 : $1, i, -1, -i, 1, \dots$.');
SELECT public._patch_cp_sma2('sma_complex_basics', 'Argument de $z = i$ :', '$z = i$ correspond au point $(0, 1)$ dans le plan complexe — sur l''**axe imaginaire positif**. L''argument est l''angle entre Ox et le vecteur $\vec{Oz}$, donc $\arg(i) = \pi/2$ (= 90°). **Forme exponentielle** : $i = e^{i\pi/2}$. C''est cohérent avec la rotation de 90° qu''incarne la multiplication par $i$.');
SELECT public._patch_cp_sma2('sma_complex_basics', 'Conjugué de $3 - 2i$ :', '**Conjugué** : $\overline{a + bi} = a - bi$ (signe imaginaire changé). Pour $3 - 2i$ : $\overline{3 - 2i} = 3 + 2i$. **Propriétés clés** : $z\bar{z} = |z|^2$ (réel positif) ; $\overline{\bar{z}} = z$ ; conjugué d''une somme/produit = somme/produit des conjugués. Sert à simplifier $1/(a+bi)$.');
SELECT public._patch_cp_sma2('sma_counting', '$X \sim \mathcal{B}(20, 0{,}3)$ : $E(X) = ?$', 'Pour une **loi binomiale** $X \sim \mathcal{B}(n, p)$, l''espérance est $E(X) = np$. Application : $E(X) = 20 \times 0{,}3 = 6$. **Interprétation** : sur 20 essais avec 30% de réussite chacun, on s''attend en moyenne à 6 succès. La variance vaut $V(X) = np(1-p) = 4{,}2$, écart-type $\sigma \approx 2{,}05$.');
SELECT public._patch_cp_sma2('sma_counting', 'Probabilité d\''obtenir 6 sur un dé équilibré :', 'Dé équilibré à 6 faces : chaque face équiprobable, donc $P(\text{obtenir 6}) = 1/6 \approx 0{,}167$. **Définition probabilité uniforme** : $P(A) = \dfrac{\text{cas favorables}}{\text{cas possibles}}$. Valable seulement si toutes les issues sont équiprobables (dé non truqué).');
SELECT public._patch_cp_sma2('sma_counting', 'Nombre d\''anagrammes de MATH :', '« MATH » contient 4 lettres **toutes distinctes**. Le nombre d''arrangements = nombre de permutations = $4! = 24$. **Si certaines lettres se répétaient** (ex : MAMA), il faudrait diviser par les factorielles des répétitions : $4!/(2!2!) = 6$ pour MAMA. Mais ici toutes différentes → simple factorielle.');
SELECT public._patch_cp_sma2('sma_counting', 'Choisir 3 personnes parmi 10 :', 'On choisit 3 parmi 10 **sans tenir compte de l''ordre** : c''est un **combinaison**, $\binom{10}{3} = \dfrac{10!}{3! \cdot 7!} = \dfrac{10 \cdot 9 \cdot 8}{6} = 120$. **Distinction clé** : combinaison (sans ordre, 120) vs arrangement (avec ordre, $A_{10}^3 = 720$). Si l''ordre comptait, on prendrait $A_{10}^3 = 10 \cdot 9 \cdot 8 = 720$.');
SELECT public._patch_cp_sma2('sma_counting', '$P(A) = 0{,}3$, $P(B) = 0{,}5$, indépendants : $P(A \cap B) = ?$', '$A$ et $B$ **indépendants** : par définition, $P(A \cap B) = P(A) \cdot P(B) = 0{,}3 \times 0{,}5 = 0{,}15$. **Attention** : indépendance ≠ incompatibilité. Indépendant = sans influence ; incompatible = ne peuvent coexister ($P(A\cap B) = 0$). Deux événements peuvent être l''un sans être l''autre.');
SELECT public._patch_cp_sma2('sma_daniell_cell_basics', '$Zn \to Zn^{2+} + 2e^-$ est une :', 'Cette demi-équation montre que $Zn$ **perd 2 électrons** pour devenir $Zn^{2+}$. **Perte d''électrons = oxydation** (mémo OIL : Oxidation Is Loss). Dans la pile Daniell, l''oxydation du zinc se produit à l''anode (pôle négatif). Les électrons libérés circulent dans le circuit extérieur jusqu''à la cathode.');
SELECT public._patch_cp_sma2('sma_daniell_cell_basics', 'L\''électrolyse :', 'Une **électrolyse** est l''inverse d''une pile : on **fournit de l''énergie électrique** pour forcer une réaction redox **non spontanée**. Exemple : électrolyse de l''eau (H₂O → H₂ + ½O₂), production d''aluminium. Une pile, à l''inverse, transforme une réaction spontanée en énergie électrique.');
SELECT public._patch_cp_sma2('sma_daniell_cell_basics', 'Pile Daniell standard : $\Delta E^\circ$ vaut :', '$\Delta E^\circ = E^\circ_{\text{cathode}} - E^\circ_{\text{anode}} = E^\circ(Cu^{2+}/Cu) - E^\circ(Zn^{2+}/Zn) = 0{,}34 - (-0{,}76) = 1{,}10$ V. C''est la **fem standard** de la pile Daniell — sa tension à vide en conditions standard. **Règle** : la cathode est l''électrode au potentiel le plus élevé.');
SELECT public._patch_cp_sma2('sma_daniell_cell_basics', 'Dans la pile Daniell, les électrons circulent :', 'Dans le **circuit extérieur** (le fil conducteur), les électrons partent de l''**anode (Zn)** où l''oxydation les libère, vers la **cathode (Cu)** où la réduction les consomme. **Sens conventionnel du courant** : opposé au sens des électrons (de Cu vers Zn dans le circuit extérieur). À l''intérieur, les ions assurent la fermeture du circuit.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Si $f\''(3) = -2$, la tangente en $x = 3$ a pour pente :', '**Définition fondamentale** : $f''(a)$ EST la pente de la tangente à la courbe $y = f(x)$ au point d''abscisse $a$. Donc si $f''(3) = -2$, la tangente en $x = 3$ a pour pente $-2$. Pente négative ⇒ tangente descendante ⇒ $f$ décroissante localement en $x = 3$.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Quel est le taux d''accroissement de $f(x) = x^2$ entre 1 et 3 ?', 'Le **taux d''accroissement** entre $a$ et $b$ : $\tau = \dfrac{f(b) - f(a)}{b - a}$. Application : $\tau = \dfrac{f(3) - f(1)}{3 - 1} = \dfrac{9 - 1}{2} = 4$. C''est la pente de la **corde** entre $(1, 1)$ et $(3, 9)$. La dérivée $f''(a)$ est la limite de ce taux quand $b \to a$.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Quelle est la dérivée de $f(x) = x^4$ ?', '**Règle des puissances** : $(x^n)'' = n x^{n-1}$. Avec $n = 4$ : $(x^4)'' = 4 x^3$. **Vérification** : pour $f(x) = x^4 = x \cdot x \cdot x \cdot x$, par la règle du produit étendue, on retrouve bien $4 x^3$. Cette règle est l''une des plus utilisées du programme — à mémoriser.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Quelle est la dérivée de $g(x) = e^x$ ?', '$(e^x)'' = e^x$ — l''exponentielle est **sa propre dérivée**. C''est sa **propriété caractéristique** : unique solution de $f'' = f$ avec $f(0) = 1$. Cela explique son omniprésence en physique (désintégration, charge de condensateur, croissance de population) — partout où la vitesse est proportionnelle à la quantité.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Un point où $f''$ s''annule en changeant de signe est :', 'Un point où $f'' = 0$ est un **point critique**. Si $f''$ change de signe :  passage de $+$ à $-$ ⇒ **maximum local** ($f$ croît puis décroît) ; passage de $-$ à $+$ ⇒ **minimum local**. **Si $f''$ ne change pas de signe** (ex : $f(x) = x^3$ en 0), c''est un point d''inflexion à tangente horizontale — pas un extremum.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Si $f''(x) > 0$ sur $]a, b[$, alors $f$ est :', '**Théorème de variation** : $f$ dérivable et $f'' > 0$ sur un intervalle ⇒ $f$ **strictement croissante** sur cet intervalle. Pente positive partout = courbe qui monte. Réciproquement, $f'' < 0$ ⇒ décroissante ; $f'' = 0$ ⇒ constante. Outil clé pour étudier les variations d''une fonction.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Que vaut la dérivée de $g(x) = \dfrac{1}{x^2 + 1}$ ?', '**Composition** $1/u$ avec $u = x^2 + 1$. **Règle** : $(1/u)'' = -u''/u^2$. Calcul : $u'' = 2x$, donc $g''(x) = -\dfrac{2x}{(x^2+1)^2}$. **Vérification de signe** : pour $x > 0$, $g'' < 0$ (dérivée négative car $g$ est décroissante là) ; pour $x < 0$, $g'' > 0$. Cohérent avec la cloche de $g$ centrée en 0.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Que vaut $h''(x)$ pour $h(x) = -2x^3 + 7$ ?', '**Linéarité** de la dérivation : $(af + bg)'' = af'' + bg''$. Calcul terme à terme : $(-2x^3)'' = -2 \cdot 3x^2 = -6x^2$ ; $(7)'' = 0$ (constante). Somme : $h''(x) = -6x^2$. **Remarque** : $h''(x) \le 0$ pour tout $x$, donc $h$ est décroissante sur $\mathbb{R}$ (avec un point critique en 0).');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'La dérivée de $f(x) = x \cdot \sin x$ est :', '**Règle du produit** : $(uv)'' = u''v + uv''$. Avec $u = x$ ($u'' = 1$) et $v = \sin x$ ($v'' = \cos x$) : $f''(x) = 1 \cdot \sin x + x \cdot \cos x = \sin x + x \cos x$. **Erreur classique** : écrire $f'' = u'' v'' = \cos x$, ce qui est **faux** — la dérivée d''un produit n''est PAS le produit des dérivées.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Une droite de pente 2 passant par $(0, 1)$ a pour équation :', 'Forme générale d''une droite : $y = mx + p$ où $m$ est la pente et $p$ l''ordonnée à l''origine (valeur en $x=0$). Ici $m = 2$ et la droite passe par $(0, 1)$, donc $p = 1$. **Équation finale** : $y = 2x + 1$. Vérification : en $x = 0$, $y = 1$ ✓ ; pente = 2 ✓.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Sur le graphe de $x \mapsto x^2$, la pente de la tangente en $x = 0$ vaut :', 'En $x = 0$, la parabole $y = x^2$ admet un **minimum** : la tangente y est **horizontale**, donc de pente 0. **Vérification analytique** : $f''(x) = 2x$, donc $f''(0) = 0$ — cohérent. **Mémo** : à un extremum d''une fonction dérivable, la tangente est toujours horizontale.');
SELECT public._patch_cp_sma2('sma_deriv_definition', 'Pour $f(x) = x^2$, le nombre dérivé en 0 vaut :', 'Deux approches. (1) Par définition : $f''(0) = \lim_{h \to 0} \dfrac{(0+h)^2 - 0}{h} = \lim_{h \to 0} h = 0$. (2) Directement : $f''(x) = 2x$ (règle des puissances), donc $f''(0) = 0$. **Cohérent** avec la tangente horizontale au minimum de la parabole.');
SELECT public._patch_cp_sma2('sma_divisibility', '$15 \equiv ? \;[4]$', 'On cherche le **reste** de la division euclidienne de 15 par 4. Calcul : $15 = 4 \cdot 3 + 3$, donc $15 \equiv 3 \pmod{4}$. **Rappel** : $a \equiv b \pmod{n}$ ssi $a - b$ est multiple de $n$, ou de manière équivalente, $a$ et $b$ ont le même reste modulo $n$. **Mémo** : le reste est toujours dans $[0, n-1]$.');
SELECT public._patch_cp_sma2('sma_divisibility', '17 est-il premier ?', '**17 est premier** : ses seuls diviseurs positifs sont 1 et 17 lui-même. **Test pratique** : pour vérifier si $n$ est premier, il suffit de tester les diviseurs jusqu''à $\sqrt{n}$. Pour 17 : $\sqrt{17} \approx 4{,}1$, on teste 2, 3 : 17/2 non entier, 17/3 non entier. Donc 17 premier.');
SELECT public._patch_cp_sma2('sma_divisibility', 'Reste de 25 par 7 :', 'Division euclidienne : $25 = 7 \cdot 3 + 4$, donc le reste est 4. On vérifie que $0 \le 4 < 7$ — c''est bien un reste valide. En notation modulo : $25 \equiv 4 \pmod{7}$. Le quotient (3) et le reste (4) sont uniquement déterminés par cette équation.');
SELECT public._patch_cp_sma2('sma_divisibility', 'pgcd = 1, on dit :', 'Deux entiers $a, b$ tels que $\gcd(a, b) = 1$ sont dits **premiers entre eux** (ou copremiers). **Attention** : être premier entre eux n''implique pas que chacun soit premier. Exemple : 4 et 9 sont premiers entre eux ($\gcd = 1$) mais ni 4 ni 9 ne sont premiers. **Théorème de Bézout** : $a, b$ premiers entre eux ⇔ il existe $u, v$ tels que $au + bv = 1$.');
SELECT public._patch_cp_sma2('sma_e_field_basics', 'Sur une charge $q < 0$ dans $\vec{E}$, la force est :', '$\vec{F} = q\vec{E}$. Pour $q > 0$, $\vec{F}$ est dans le sens de $\vec{E}$ ; pour **$q < 0$, $\vec{F}$ est opposée à $\vec{E}$**. C''est pourquoi un électron ($q = -e < 0$) dans un champ électrique pointant vers la droite est dévié vers la gauche.');
SELECT public._patch_cp_sma2('sma_e_field_basics', '$U = 100$ V, $d = 0{,}1$ m. $E = ?$', 'Pour un champ uniforme entre deux plaques planes parallèles, $E = U/d$. Application : $E = 100/0{,}1 = 1000$ V/m. **Unités** : V/m ou N/C (équivalent). **Direction** : de la plaque + vers la plaque −. Plus $U$ est grand ou plus $d$ est petit, plus $E$ est intense.');
SELECT public._patch_cp_sma2('sma_e_field_basics', 'Si on double $U$, la déviation à la sortie :', 'La déviation $y$ d''une charge entre les plaques d''un condensateur est proportionnelle à l''accélération $a = qE/m$, donc à $E$, donc à $U$ (puisque $E = U/d$). **Conclusion** : $y \propto U$ — doubler $U$ **double la déviation**. Application : déflexion dans un oscilloscope cathodique.');
SELECT public._patch_cp_sma2('sma_e_field_basics', 'Un électron est dévié vers la plaque :', 'L''électron porte une charge $q = -e < 0$. La force électrique $\vec{F} = q\vec{E}$ pour $q < 0$ est **opposée à $\vec{E}$**. Or $\vec{E}$ va de la plaque + vers la plaque −. Donc $\vec{F}$ va de − vers +, et **l''électron est attiré par la plaque positive**. **Mémo** : les charges − vont vers le +.');
SELECT public._patch_cp_sma2('sma_esterification_mechanism', 'L''éthanol est :', 'L''éthanol a la formule $CH_3-CH_2-OH$, soit $C_2H_6O$. Il appartient à la famille des **alcools** (groupe fonctionnel $-OH$ porté par un carbone tétraédrique non aromatique). C''est un alcool primaire (le carbone porteur de OH a 1 H). Utilisé en estérification pour donner des esters de petite chaîne.');
SELECT public._patch_cp_sma2('sma_esterification_mechanism', 'Un catalyseur en estérification :', 'Un **catalyseur** (typiquement $H_2SO_4$ concentré) **accélère la réaction sans la déplacer**. Il agit sur la **vitesse uniquement** : on atteint l''équilibre plus rapidement, mais le rendement final est le même (~67% pour mélange équimolaire). Pour augmenter le rendement, il faut déplacer l''équilibre (élimination de l''eau, excès de réactif).');
SELECT public._patch_cp_sma2('sma_esterification_mechanism', 'La saponification est :', 'La **saponification** est l''hydrolyse d''un ester en milieu **basique** (ex : NaOH) — réaction inverse de l''estérification mais **totale**. L''ion hydroxyde déprotone l''acide formé en carboxylate, déplaçant l''équilibre vers les produits. Application industrielle majeure : fabrication de savons à partir de corps gras (triglycérides).');
SELECT public._patch_cp_sma2('sma_esterification_mechanism', 'L''estérification est :', 'L''estérification (acide + alcool → ester + eau) est **limitée** par un équilibre (rendement plafonné autour de 67% pour mélange équimolaire) et **lente** sans catalyseur (heures à température ambiante). On l''accélère par catalyseur acide ($H_2SO_4$) et on déplace l''équilibre en éliminant l''eau (Dean-Stark).');
SELECT public._patch_cp_sma2('sma_exp_basics', 'Solution de $e^x = 5$ :', 'On applique le logarithme népérien aux deux membres : $\ln(e^x) = \ln 5$, soit $x = \ln 5$ (par bijection $\ln \circ \exp = \text{id}$). **Numériquement** : $\ln 5 \approx 1{,}609$. **Méthode générale** : pour $e^x = a$ (avec $a > 0$), la solution unique est $x = \ln a$.');
SELECT public._patch_cp_sma2('sma_exp_basics', '$\lim_{x \to -\infty} e^x$ :', 'Quand $x \to -\infty$, $e^x \to 0$. **Asymptote horizontale** $y = 0$ en $-\infty$. **Intuition** : $e^{-1000} \approx 10^{-434}$, infinitésimal. La fonction reste strictement positive ($e^x > 0$ partout), s''approchant de 0 sans jamais l''atteindre. À l''inverse : $\lim_{x\to+\infty} e^x = +\infty$.');
SELECT public._patch_cp_sma2('sma_exp_basics', '$\lim_{x \to +\infty} \dfrac{e^x}{x^{100}}$ :', '**Théorème des croissances comparées** : à l''infini, l''exponentielle l''emporte sur n''importe quelle puissance. $\lim_{x\to+\infty} \dfrac{e^x}{x^n} = +\infty$ pour tout $n$. Donc $\dfrac{e^x}{x^{100}} \to +\infty$. **Intuition** : $e^x$ croît exponentiellement, $x^{100}$ croît polynomialement — très vite, l''exponentielle écrase tout.');
SELECT public._patch_cp_sma2('sma_exp_basics', '$(e^{-x})''$ vaut :', 'Composition de $e^u$ avec $u = -x$. **Règle** : $(e^u)'' = u'' \cdot e^u$. Ici $u'' = -1$, donc $(e^{-x})'' = -e^{-x}$. **Mémo** : la dérivée garde l''exponentielle et multiplie par la dérivée de l''exposant. Cela explique pourquoi $e^{-x}$ est décroissante (dérivée négative).');
SELECT public._patch_cp_sma2('sma_exp_basics', '$e^{-2}$ vaut :', '$e^{-a} = 1/e^a$ — l''exposant négatif transforme en inverse. Donc $e^{-2} = 1/e^2 \approx 1/7{,}389 \approx 0{,}135$. **Plus généralement** : pour tout $a$, $e^{-a} \cdot e^a = e^0 = 1$, ce qui définit l''inverse. Cette propriété rend les calculs avec exposants négatifs simples.');
SELECT public._patch_cp_sma2('sma_exp_basics', '$e^x$ est :', '$e^x > 0$ pour **tout** $x \in \mathbb{R}$ — l''exponentielle ne s''annule jamais et est toujours positive. C''est une **propriété fondamentale** : utile pour résoudre des équations (on peut diviser par $e^x$ sans souci) et pour étudier des inéquations (les inégalités se conservent en multipliant par $e^x$).');
SELECT public._patch_cp_sma2('sma_exp_basics', '$\ln(e^x) = ?$', '$\ln(e^x) = x$ pour tout $x \in \mathbb{R}$. C''est la **bijection** : $\ln$ et $\exp$ sont **fonctions réciproques** l''une de l''autre, donc leur composition est l''identité. De même $e^{\ln x} = x$ pour $x > 0$. **Application** : pour résoudre $e^x = a$, on prend $\ln$ : $x = \ln a$.');
SELECT public._patch_cp_sma2('sma_exp_basics', '$2^3 \cdot 2^4$ vaut :', '**Règle des exposants** : $a^m \cdot a^n = a^{m+n}$ — quand on multiplie deux puissances de **même base**, on additionne les exposants. Application : $2^3 \cdot 2^4 = 2^{3+4} = 2^7 = 128$. **Vérification directe** : $2^3 = 8$, $2^4 = 16$, $8 \times 16 = 128$ ✓.');
SELECT public._patch_cp_sma2('sma_forced_oscillations', 'Plus $Q$ est grand :', 'Le **facteur de qualité** $Q = L\omega_0/R$ caractérise la sélectivité d''un circuit RLC. Plus $Q$ est grand, **plus la résonance est aiguë** : pic étroit, hauteur élevée, faible bande passante $\Delta\omega = \omega_0/Q$. À l''inverse, $Q$ faible = pic large et plat, peu sélectif.');
SELECT public._patch_cp_sma2('sma_forced_oscillations', 'Pour sélectionner une station radio, on cherche :', 'Pour séparer deux stations radio voisines en fréquence, il faut un circuit **très sélectif** — donc une **résonance aiguë**, c''est-à-dire $Q$ grand. Le circuit ne laisse passer que les fréquences proches de $\omega_0$ ; les stations voisines sont fortement atténuées. **Mémo** : tuner radio = circuit RLC à fort $Q$, ajustable via $C$ variable.');
SELECT public._patch_cp_sma2('sma_forced_oscillations', 'L\''impédance $Z$ est minimale quand :', 'L''impédance d''un RLC série est $Z = \sqrt{R^2 + (L\omega - 1/(C\omega))^2}$. À la **pulsation propre $\omega = \omega_0 = 1/\sqrt{LC}$**, le terme $L\omega - 1/(C\omega)$ s''annule — il reste $Z = R$ (minimum). Le courant est alors **maximal**. C''est la **résonance d''intensité**.');
SELECT public._patch_cp_sma2('sma_forced_oscillations', 'Pulsation propre d\''un LC : $\omega_0 = ?$', 'Pour un circuit LC idéal (sans résistance), la **pulsation propre** est $\omega_0 = \dfrac{1}{\sqrt{LC}}$ (rad/s). Période : $T_0 = 2\pi\sqrt{LC}$. **Analogie mécanique** : $L$ = inertie (masse), $C$ = inverse de la raideur. Un circuit LC est l''équivalent électrique d''un oscillateur harmonique mécanique.');
SELECT public._patch_cp_sma2('sma_kinetic_potential', 'Unité d\''énergie SI :', 'L''unité SI de l''énergie est le **joule (J)** : $1\,\text{J} = 1\,\text{N} \cdot \text{m} = 1\,\text{kg} \cdot \text{m}^2/\text{s}^2$. Autres unités courantes : calorie (1 cal ≈ 4,18 J), électron-volt (1 eV ≈ 1,6 × 10⁻¹⁹ J en physique des particules), kWh (1 kWh = 3,6 × 10⁶ J en énergie domestique).');
SELECT public._patch_cp_sma2('sma_kinetic_potential', 'Si on double $v$, $E_c$ :', '$E_c = \dfrac{1}{2} m v^2$ — proportionnelle au **carré** de la vitesse. Doubler $v$ **quadruple** $E_c$ ($\times 4$). Application : un véhicule à 100 km/h a 4× l''énergie d''un véhicule à 50 km/h, d''où la croissance rapide de la distance de freinage. Cette relation quadratique est cruciale pour la sécurité routière.');
SELECT public._patch_cp_sma2('sma_kinetic_potential', 'Sans frottement, $E_m$ :', 'En l''absence de frottement (ou autres forces non conservatives), l''**énergie mécanique** $E_m = E_c + E_p$ se **conserve** : pas de dissipation, $E_m$ = constante. C''est le **principe de conservation** en mécanique. Avec frottements : $E_m$ diminue, l''énergie est dissipée en chaleur.');
SELECT public._patch_cp_sma2('sma_kinetic_potential', 'Au point le plus haut d''un pendule, $E_c$ est :', 'Au point le plus haut d''un pendule, la vitesse est **nulle** (la masse change de sens). Donc $E_c = \dfrac{1}{2} m \cdot 0^2 = 0$ — **toute l''énergie est en $E_p$ gravitationnelle**. Au point le plus bas (passage par la verticale), c''est l''inverse : $E_p$ minimum, $E_c$ maximum. La somme $E_m$ est constante.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Que vaut $\lim_{x \to +\infty} \dfrac{1}{x}$ ?', 'Quand $x \to +\infty$, le numérateur 1 reste fixe et le dénominateur $x$ devient arbitrairement grand. Une fraction « constante / quelque chose qui tend vers $\infty$ » tend vers 0. **Limite = 0**. C''est l''archétype de la décroissance vers 0 à l''infini, fondement des asymptotes horizontales.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Vers quoi tend $\dfrac{2x+1}{x+3}$ quand $x \to +\infty$ ?', 'Forme indéterminée $\infty/\infty$. **Astuce** : factoriser $x$ haut et bas. $\dfrac{2x+1}{x+3} = \dfrac{x(2 + 1/x)}{x(1 + 3/x)} = \dfrac{2 + 1/x}{1 + 3/x} \to \dfrac{2}{1} = 2$. **Règle rapide** : pour un quotient de polynômes de **même degré** à l''infini, la limite est le rapport des coefficients dominants.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Quelle est $\displaystyle\lim_{x\to 4} \dfrac{x^2 - 16}{x-4}$ ?', 'Substitution en $x = 4$ : numérateur $0$, dénominateur $0$, **forme indéterminée $0/0$**. On factorise via l''identité $a^2 - b^2 = (a-b)(a+b)$ : $x^2 - 16 = (x-4)(x+4)$. Le facteur $(x-4)$ se simplifie, il reste $\lim_{x\to 4}(x+4) = 8$. **Pattern** : $0/0 \Rightarrow$ chercher une factorisation cachée.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Quelle est $\displaystyle\lim_{x\to +\infty} \dfrac{3x+1}{x+5}$ ?', 'Quotient de polynômes de **même degré** à l''infini → la limite est le **rapport des coefficients dominants**. $\dfrac{3x+1}{x+5} \to \dfrac{3}{1} = 3$. **Démonstration formelle** : factoriser $x$ haut et bas, $\dfrac{3 + 1/x}{1 + 5/x} \to 3$. **Règle générale** : numérateur degré > dénominateur ⇒ $\pm\infty$ ; égal ⇒ rapport ; <  ⇒ 0.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Que vaut $\displaystyle\lim_{x\to 0^+} \dfrac{1}{x}$ ?', 'Limite **à droite** de 0 ($x \to 0$ avec $x > 0$). Le dénominateur tend vers 0 par valeurs positives, $1/x$ devient arbitrairement grand et positif → $+\infty$. **Attention au signe** : à gauche, $\lim_{x\to 0^-} 1/x = -\infty$. La limite globale **n''existe pas** car les limites latérales diffèrent.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Et $\displaystyle\lim_{x\to +\infty} \dfrac{x^2+1}{x+2}$ ?', 'Quotient avec **degré numérateur (2) > degré dénominateur (1)** : le numérateur l''emporte, la limite est $\pm\infty$. Pour le signe : factoriser $x$ haut ($\dfrac{x(x + 1/x)}{x(1 + 2/x)} = \dfrac{x + 1/x}{1 + 2/x}$), on voit que numérateur $\to +\infty$ et dénominateur $\to 1$, donc **limite = $+\infty$**.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Une fonction $f$ telle que $\lim_{x\to 2} f(x) = 5$ et $f(2) = 5$ est :', 'C''est exactement la **définition de la continuité en 2** : la limite égale la valeur. Trois conditions équivalentes : (1) $f$ définie en 2, (2) la limite existe en 2, (3) la limite = $f(2)$. Géométriquement : on trace la courbe en passant par le point $(2, 5)$ sans lever le crayon.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Le TVI permet de :', 'Le **théorème des valeurs intermédiaires** garantit l''**existence** d''une solution sans donner sa valeur. Si $f$ continue sur $[a,b]$ et $k$ entre $f(a)$ et $f(b)$, alors $\exists c \in [a,b] : f(c) = k$. Théorème d''**existence pure**. Corollaire le plus utilisé : $f(a)f(b) < 0$ ⇒ $f$ s''annule au moins une fois entre $a$ et $b$.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Soit $g$ continue sur $[0,1]$, avec $g(0) = 3$ et $g(1) = -2$. Le TVI garantit qu\''il existe $c \in [0,1]$ tel que :', 'Le TVI s''applique aux valeurs **entre** $g(0) = 3$ et $g(1) = -2$, soit $[-2, 3]$. **0 est dans cet intervalle** ($-2 < 0 < 3$), donc $\exists c \in ]0,1[ : g(c) = 0$. Les valeurs 5, $-3$, 4 sont **en dehors** de $[-2, 3]$ — le TVI ne dit rien d''elles dans ce cas.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Que vaut $\lim_{x \to 0} x^2$ ?', '$x \mapsto x^2$ est **polynômiale** donc continue sur $\mathbb{R}$. Pour une fonction continue, $\lim_{x \to a} f(x) = f(a)$ — substitution directe. Application : $\lim_{x \to 0} x^2 = 0^2 = 0$. **Toujours essayer la substitution directe avant les techniques avancées** — souvent ça suffit.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Simplifie $\dfrac{2x^2 - 8}{x - 2}$ pour $x \ne 2$.', 'Factoriser le numérateur : $2x^2 - 8 = 2(x^2 - 4) = 2(x-2)(x+2)$ via l''identité $a^2 - b^2$. La fraction devient $\dfrac{2(x-2)(x+2)}{x-2} = 2(x+2) = 2x + 4$ (légitime car $x \ne 2$, donc $x - 2 \ne 0$). **Application** : ce type de simplification sert à lever des formes indéterminées $0/0$.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Quel est l''ensemble de définition de $f(x) = \dfrac{1}{x-1}$ ?', 'Une fraction n''est définie que si son dénominateur est non nul. Ici $x - 1 = 0 \iff x = 1$. Donc $f$ est définie pour tout $x \ne 1$, soit **$\mathbb{R} \setminus \{1\}$** ou $]-\infty, 1[\,\cup\,]1, +\infty[$. **Toujours vérifier l''ensemble de définition** avant tout calcul de limite ou de dérivée.');
SELECT public._patch_cp_sma2('sma_limit_def', 'Factorise $x^2 - 9$.', 'C''est une **différence de carrés** : $x^2 - 9 = x^2 - 3^2$. Identité remarquable $a^2 - b^2 = (a-b)(a+b)$ avec $a = x$ et $b = 3$. **Résultat** : $x^2 - 9 = (x-3)(x+3)$. Vérification par développement : $(x-3)(x+3) = x^2 + 3x - 3x - 9 = x^2 - 9$ ✓. Cette factorisation est partout en calcul de limites.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Que vaut $\ln(e^3)$ ?', 'Par la propriété de **bijection** : $\ln(e^x) = x$ pour tout $x \in \mathbb{R}$. Donc $\ln(e^3) = 3$. **Justification** : $\ln$ et $\exp$ sont fonctions réciproques, leur composition est l''identité. **Remarque** : le résultat est un nombre simple, sans logarithme — c''est l''intérêt de cette propriété pour simplifier les expressions.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Combien vaut $e^0$ ?', '$e^0 = 1$. **Plus généralement** : pour toute base $a > 0$, $a^0 = 1$. C''est la convention standard des puissances, cohérente avec la règle $a^{m-n} = a^m/a^n$ qui pour $m = n$ donne $a^0 = 1$. Application : $e^0$ apparaît souvent dans les solutions d''équations différentielles à $t = 0$.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Si $e^x = 1$, alors $x$ vaut :', 'Application de $\ln$ aux deux membres : $x = \ln 1 = 0$. **Cohérent** : $e^0 = 1$ par définition de l''exponentielle. **Plus généralement** : $\ln 1 = 0$ est l''unique solution de $e^x = 1$, parce que $\exp$ est une bijection strictement croissante.');
SELECT public._patch_cp_sma2('sma_ln_basics', '$\ln(2x)$ s\''écrit aussi :', '**Propriété fondamentale** du logarithme : $\ln(ab) = \ln a + \ln b$ (transforme produit en somme, pour $a, b > 0$). Application : $\ln(2x) = \ln 2 + \ln x$. **Erreur classique** : écrire $\ln(2x) = 2\ln x$ — **faux**, ça c''est $\ln(x^2)$. La règle $\ln(x^n) = n \ln x$ s''applique aux puissances, pas aux coefficients.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Si $\ln x = 2$, alors $x$ vaut :', 'On applique $\exp$ aux deux membres : $e^{\ln x} = e^2$, soit $x = e^2 \approx 7{,}389$. **Bijection** : $\ln x = 2 \iff x = e^2$. **Méthode générale** : pour résoudre $\ln x = a$, prendre $x = e^a$ (avec $x > 0$ requis car $\ln$ n''est définie que sur $]0, +\infty[$).');
SELECT public._patch_cp_sma2('sma_ln_basics', '$(\ln(x^2))\''$ vaut :', '**Composition** : $(\ln u)'' = u''/u$ avec $u = x^2$. Calcul : $u'' = 2x$, donc $(\ln(x^2))'' = \dfrac{2x}{x^2} = \dfrac{2}{x}$. **Vérification alternative** : $\ln(x^2) = 2\ln|x|$, dont la dérivée est $2 \cdot 1/x = 2/x$ ✓. Cohérent.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Solution de $\ln x = 1$ :', 'Par définition même : $\ln e = 1$. Donc $\ln x = 1 \iff x = e \approx 2{,}718$. **Méthode générale** : pour $\ln x = a$, prendre $x = e^a$. **Remarque** : $e$ est défini précisément comme le réel tel que $\ln e = 1$ — c''est la base naturelle des logarithmes.');
SELECT public._patch_cp_sma2('sma_ln_basics', '$\lim_{x \to +\infty} \dfrac{\ln x}{x^2}$ vaut :', '**Théorème des croissances comparées** : à l''infini, toute puissance positive de $x$ l''emporte sur $\ln x$. $\lim_{x\to+\infty} \dfrac{\ln x}{x^\alpha} = 0$ pour tout $\alpha > 0$. Application : $\dfrac{\ln x}{x^2} \to 0$. **Hiérarchie de croissance** : exponentielle $\gg$ puissance $\gg$ logarithme.');
SELECT public._patch_cp_sma2('sma_ln_basics', 'Domaine de $\ln(x^2 - 4)$ ?', 'Le logarithme népérien n''est défini que pour les arguments **strictement positifs**. Condition : $x^2 - 4 > 0 \iff x^2 > 4 \iff |x| > 2 \iff x \in ]-\infty, -2[ \cup ]2, +\infty[$. **Erreur classique** : prendre $x \ne \pm 2$ (qui n''autorise que la non-annulation). Ici il faut **strictement positif**, pas juste non nul.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un objet en MRU parcourt 100 m en 4 s. Sa vitesse est :', '**MRU** = Mouvement Rectiligne Uniforme : vitesse constante. Formule : $v = d/t = 100/4 = 25$ m/s. Conversion : $25 \text{ m/s} \times 3{,}6 = 90$ km/h. **Cohérence** : en MRU, l''accélération est nulle, le déplacement est proportionnel au temps.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un vecteur $\vec{F}$ a une norme de 10 N et fait un angle de 60° avec l''axe Ox. Sa composante $F_x$ vaut :', '**Projection** d''un vecteur sur l''axe Ox : $F_x = F \cos\theta = 10 \cdot \cos 60° = 10 \times 0{,}5 = 5$ N. **Mémo** : $\cos 60° = 1/2$, $\sin 60° = \sqrt{3}/2$. La composante $F_y = F \sin 60° = 10 \cdot \sqrt{3}/2 \approx 8{,}66$ N. Le module est conservé : $\sqrt{F_x^2 + F_y^2} = 10$ N ✓.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Une accélération constante de $2$ m/s² signifie que :', '**Définition** : l''accélération est la variation de vitesse par unité de temps. $a = 2$ m/s² signifie que la vitesse **augmente de 2 m/s à chaque seconde**. À $t = 0$ avec $v_0 = 0$, à $t = 1$ s, $v = 2$ m/s ; à $t = 5$ s, $v = 10$ m/s. Pour $g \approx 9{,}8$ m/s², la vitesse en chute libre augmente de ~10 m/s par seconde.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un mobile a pour position $x(t) = 3t^2 + 5$. Sa vitesse à $t=2$s vaut :', '**Définition** : $v(t) = dx/dt$ — dérivée de la position. Calcul : $v(t) = (3t^2 + 5)'' = 6t$. À $t = 2$ s : $v(2) = 12$ m/s. **Vérification** : à $t = 0$, vitesse = 0 (le mobile démarre du repos). Accélération $a(t) = v''(t) = 6$ m/s² constante — c''est un MRUA.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un objet en mouvement à vitesse constante en ligne droite est soumis à :', '**1ère loi de Newton (principe d''inertie)** : MRU ⇔ $\sum \vec{F} = \vec{0}$. Cela ne signifie PAS « aucune force », mais que la **résultante** est nulle. Plusieurs forces peuvent s''exercer (ex : une voiture à vitesse constante a moteur + frottements + poids + réaction du sol — somme nulle).');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Si $\Sigma \vec{F} = 10\,\vec{i}$ N s\''applique à un objet de $m = 2$ kg, son accélération vaut :', '**RFD (2ème loi de Newton)** : $\sum \vec{F} = m \vec{a}$, donc $\vec{a} = \dfrac{\sum \vec{F}}{m} = \dfrac{10}{2} \vec{i} = 5\,\vec{i}$ m/s². L''accélération est dans le sens de la force résultante. **Unités** : N/kg = m/s² ✓.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un livre posé sur une table. La réaction de la table sur le livre :', '**3ème loi de Newton** : la table exerce sur le livre une force $\vec{R}$, qui est la réaction à la force que le livre exerce sur la table. Sur le livre, deux forces agissent : son **poids** $\vec{P}$ (vers le bas) et **$\vec{R}$** (vers le haut). À l''équilibre (livre immobile), $\vec{P} + \vec{R} = \vec{0}$ — c''est la 1ère loi. **Attention** : $\vec{R}$ et $\vec{P}$ ne sont PAS un couple action/réaction (ils s''exercent sur le même objet).');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Distance parcourue dans le même cas ($v_0=0$, $a=2$ m/s², $t=5$ s) :', '**Équation du MRUA** : $x(t) = x_0 + v_0 t + \dfrac{1}{2} a t^2$. Avec $x_0 = 0$, $v_0 = 0$ : $x = \dfrac{1}{2} a t^2 = \dfrac{1}{2} \times 2 \times 25 = 25$ m. **Vérification** : la vitesse moyenne sur $[0, 5]$ s est $v_\text{moy} = (0 + 10)/2 = 5$ m/s, donc distance = $5 \times 5 = 25$ m ✓.');
SELECT public._patch_cp_sma2('sma_newton_laws', 'Un mobile en MRUV part de $v_0 = 0$ avec $a = 2$ m/s². Sa vitesse à $t = 5$ s vaut :', '**Équation du MRUV (MRUA)** : $v(t) = v_0 + at$. Application : $v(5) = 0 + 2 \times 5 = 10$ m/s. À chaque seconde, la vitesse augmente de 2 m/s. **Cohérence dimensionnelle** : m/s² × s = m/s ✓.');
SELECT public._patch_cp_sma2('sma_nuclear_radioactivity', '$^{14}_6 C$ contient :', 'Notation $^A_Z X$ : $Z$ = numéro atomique = nombre de **protons** ; $A$ = nombre de masse = nombre de **nucléons** (protons + neutrons). Pour $^{14}_6 C$ : 6 protons, $14 - 6 = 8$ neutrons. Total nucléons = 14. **Note** : le nombre d''électrons (dans l''atome neutre) = nombre de protons = 6.');
SELECT public._patch_cp_sma2('sma_nuclear_radioactivity', 'La fission libère de l''énergie pour les noyaux :', 'L''énergie de liaison par nucléon est maximale autour du **fer** ($^{56}$Fe). Les noyaux **plus lourds** que le fer libèrent de l''énergie en se cassant (**fission**, ex : uranium-235 dans les réacteurs). Les noyaux **plus légers** libèrent de l''énergie en fusionnant (**fusion**, ex : hydrogène dans les étoiles).');
SELECT public._patch_cp_sma2('sma_nuclear_radioactivity', 'Au bout de $2 t_{1/2}$, il reste :', '**Demi-vie $t_{1/2}$** : durée pour que la quantité initiale soit divisée par 2. Au bout de $2 t_{1/2}$, on divise deux fois par 2, soit par 4. **Reste $1/4$** de la quantité initiale. Au bout de $n t_{1/2}$ : reste $1/2^n$. Application : carbone-14 a $t_{1/2} \approx 5730$ ans, utilisé pour la datation.');
SELECT public._patch_cp_sma2('sma_nuclear_radioactivity', 'Conservation : $A_{père} = A_{fils} + A_{particule}$. Vrai ou faux ?', '**Vrai**. Lors d''une désintégration, **deux conservations** : (1) nombre de nucléons $A$ (ce qui inclut $A_{\text{père}} = A_{\text{fils}} + A_{\text{particule}}$) ; (2) nombre de charges $Z$ (de même $Z_{\text{père}} = Z_{\text{fils}} + Z_{\text{particule}}$). Ces deux lois permettent d''identifier le noyau fils dans toute désintégration $\alpha$, $\beta^-$, $\beta^+$.');
SELECT public._patch_cp_sma2('sma_ode_first_order', '$y\'' = -y + 2$ avec $y(0) = 5$ : $y(x) = ?$', '**EDO linéaire d''ordre 1** : solution = solution générale homogène + solution particulière. Homogène $y'' = -y$ → $y_h = Ce^{-x}$. Particulière (constante) $y_p = 2$ (vérifie $0 = -2 + 2$ ✓). Solution générale : $y = Ce^{-x} + 2$. CI : $y(0) = C + 2 = 5$ → $C = 3$. **Solution** : $y(x) = 3e^{-x} + 2$.');
SELECT public._patch_cp_sma2('sma_ode_first_order', 'Décroissance radioactive obéit à :', 'La loi de désintégration radioactive : $\dfrac{dN}{dt} = -\lambda N$ — la vitesse de disparition est proportionnelle au nombre de noyaux présents. Forme $y'' = ay$ avec $a < 0$ (typiquement $a = -\lambda$, où $\lambda > 0$ est la constante radioactive). **Solution** : $N(t) = N_0 e^{-\lambda t}$ — décroissance exponentielle, demi-vie $t_{1/2} = \ln 2/\lambda$.');
SELECT public._patch_cp_sma2('sma_ode_first_order', 'Période propre de $y\''\'' + 4y = 0$ :', 'Forme oscillateur harmonique $y'''' + \omega^2 y = 0$ avec $\omega^2 = 4$, donc $\omega = 2$ rad/s. **Période** : $T = 2\pi/\omega = 2\pi/2 = \pi$ s. **Solutions** : $y(x) = A\cos(2x) + B\sin(2x)$ — oscillations sinusoïdales de période $\pi$.');
SELECT public._patch_cp_sma2('sma_ode_first_order', 'Pour $y\''\'' + 9y = 0$, $\omega$ vaut :', 'Identification avec $y'''' + \omega^2 y = 0$ : $\omega^2 = 9$, donc $\omega = 3$ rad/s (on prend la racine positive — $\omega$ représente une pulsation, par convention positive). Période $T = 2\pi/3$ s. Fréquence $f = \omega/(2\pi) = 3/(2\pi)$ Hz.');
SELECT public._patch_cp_sma2('sma_ode_first_order', 'Primitive de $3x^2$ :', 'Règle des puissances : $\int x^n\,dx = \dfrac{x^{n+1}}{n+1} + C$. Avec $n = 2$ et le coefficient 3 : $\int 3x^2\,dx = 3 \cdot \dfrac{x^3}{3} + C = x^3 + C$. **Toujours penser à la constante d''intégration $C$** — elle est libre, et toute primitive est définie à une constante près.');
SELECT public._patch_cp_sma2('sma_ode_first_order', 'Solution générale de $y\'' = 3y$ :', 'Forme $y'' = ay$ avec $a = 3$. **Solution générale** : $y(x) = Ce^{3x}$, $C \in \mathbb{R}$. La constante $C$ est déterminée par une condition initiale (ex : $y(0) = y_0$ donne $C = y_0$). **Croissance exponentielle** car $a > 0$ — modélise croissance bactérienne, intérêts composés en temps continu, etc.');
SELECT public._patch_cp_sma2('sma_pendulum_simple', 'Si on double $m$, $T_0$ :', 'Pour un **pendule simple** (de longueur $L$, masse $m$ au bout d''un fil), la période est $T_0 = 2\pi\sqrt{L/g}$ — **indépendante de la masse**. Doubler $m$ ne change rien à $T_0$. **Pour un pendule pesant** ou un système masse-ressort, la formule est $T = 2\pi\sqrt{m/k}$ et $T \propto \sqrt{m}$ — doubler $m$ multiplie $T$ par $\sqrt 2$.');
SELECT public._patch_cp_sma2('sma_pendulum_simple', 'Si $\omega_0 = 2$ rad/s, $T_0 = ?$', 'Relation période/pulsation : $T_0 = 2\pi/\omega_0 = 2\pi/2 = \pi \approx 3{,}14$ s. **Mémo** : la période est l''inverse de la fréquence, multipliée par $2\pi$ pour la pulsation. Application : un pendule de période 1 s a $\omega_0 = 2\pi$ rad/s.');
SELECT public._patch_cp_sma2('sma_pendulum_simple', 'Si on double $L$, $T_0$ :', 'Pour un pendule simple : $T_0 = 2\pi\sqrt{L/g}$, donc **$T_0 \propto \sqrt{L}$**. Doubler $L$ multiplie $T_0$ par $\sqrt{2} \approx 1{,}41$. Pour quadrupler $T_0$, il faudrait multiplier $L$ par 16. **Application historique** : Galilée a découvert l''isochronisme du pendule en observant un lustre de cathédrale.');
SELECT public._patch_cp_sma2('sma_pendulum_simple', 'Au passage par la position d''équilibre, $E_c$ est :', 'Au passage par l''équilibre, le pendule a sa **vitesse maximale** (les forces de rappel l''ont accéléré pendant la descente). Donc **$E_c$ est maximale** et **$E_p$ minimale** (= 0 si on prend l''équilibre comme référence). À l''extrémité d''oscillation : inverse, $E_c = 0$, $E_p$ maximale. La somme $E_m$ est constante (sans frottement).');
SELECT public._patch_cp_sma2('sma_periodic_waves', 'Si $f = 50$ Hz, $T = ?$', '**Relation période-fréquence** : $T = 1/f$. Application : $T = 1/50 = 0{,}02$ s = 20 ms. **Unités** : Hz = 1/s, donc T en s. C''est la fréquence du courant alternatif en Europe (la lumière vacille à 100 Hz, deux fois par cycle).');
SELECT public._patch_cp_sma2('sma_periodic_waves', 'Une onde périodique a :', 'Une onde périodique est **doublement périodique** : (1) en **temps** au point fixe (période $T$, on voit la même chose toutes les $T$ secondes) ; (2) en **espace** à un instant fixe (longueur d''onde $\lambda$, on voit la même chose tous les $\lambda$ mètres). Relation : $\lambda = vT$ ou $v = \lambda f$.');
SELECT public._patch_cp_sma2('sma_periodic_waves', '$\lambda = 2$ m, $v = 8$ m/s, alors $f = ?$', '**Relation fondamentale des ondes** : $v = \lambda f$, donc $f = v/\lambda = 8/2 = 4$ Hz. **Vérification dimensionnelle** : (m/s)/m = 1/s = Hz ✓. Période : $T = 1/f = 0{,}25$ s.');
SELECT public._patch_cp_sma2('sma_periodic_waves', 'Diffraction notable quand $a$ est :', 'Critère de **diffraction** : observable quand la dimension $a$ de l''ouverture (ou obstacle) est **comparable à $\lambda$**. L''écart angulaire $\theta \sim \lambda/a$ : $a \sim \lambda$ → diffraction nette ; $a \gg \lambda$ → propagation rectiligne, pas de diffraction visible. **Exemple** : son derrière un mur (λ ~ 1 m), oui ; lumière (λ ~ 500 nm), non.');
SELECT public._patch_cp_sma2('sma_periodic_waves', 'Si on double $\lambda$, l\''interfrange :', '**Interfrange** dans une figure d''interférences : $i = \dfrac{\lambda D}{a}$ ($D$ = distance écran-fentes, $a$ = espacement entre fentes). $i$ est **proportionnel à $\lambda$** : doubler $\lambda$ double $i$. **Application** : avec lumière rouge (λ ~ 700 nm) on a un interfrange ~1,5× celui d''une lumière violette (λ ~ 450 nm) à montage identique.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Une solution avec $\text{pH} = 9$ est :', '**Échelle de pH** : pH < 7 = acide, pH = 7 = neutre, pH > 7 = basique. pH = 9 > 7 → **solution basique**. À pH = 9, $[H_3O^+] = 10^{-9}$ mol/L (faible) et $[OH^-] = 10^{-5}$ mol/L (plus élevé). Exemples de solutions à pH ~ 9 : eau de mer, certains savons doux.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Plus le $\text{pK}_a$ est petit :', 'Relation : $\text{pK}_a = -\log K_a$. **pKa petit ⟺ $K_a$ grand ⟺ équilibre AH ⇌ A⁻ + H₃O⁺ très déplacé vers la droite ⟺ acide fort** (ou plus dissocié). À l''inverse, pKa grand = acide faible. **Repères** : HCl pKa ≈ -7 (très fort), acide acétique pKa ≈ 4,75 (faible), eau pKa = 14 (extrêmement faible).');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Pour un acide faible AH dissous dans l''eau :', 'Définition d''un **acide faible** : sa dissociation $AH + H_2O \rightleftharpoons A^- + H_3O^+$ est **partielle** — l''équilibre coexiste avec des molécules AH non dissociées. À l''opposé, un acide fort se dissocie quasi totalement. **Conséquence** : pH d''un acide faible > pH d''un acide fort à même concentration.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Pour un couple AH/A⁻ avec pKa = 6, à pH = 8 :', '**Règle de prédominance** : $\text{pH} > \text{pK}_a$ → la **base** $A^-$ domine ; pH < pKa → l''acide AH domine. À pH = 8 et pKa = 6 : pH > pKa, donc $A^-$ majoritaire. **Quantitativement** (Henderson-Hasselbalch) : $\log([A^-]/[AH]) = \text{pH} - \text{pK}_a = 2$, soit ratio 100:1.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'À pH = pKa exactement :', 'À **pH = pKa**, on est à la **frontière** de prédominance. L''équation de Henderson-Hasselbalch donne $\log([A^-]/[AH]) = 0$, soit $[A^-] = [AH]$ — concentrations égales. C''est le **point de demi-équivalence** d''un dosage acide-base, utilisé pour mesurer le pKa expérimentalement.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Dans l''eau pure à 25°C, $[\text{H}_3\text{O}^+]$ vaut :', 'L''eau pure subit une autoprotolyse : $2H_2O \rightleftharpoons H_3O^+ + OH^-$. **Produit ionique** : $K_e = [H_3O^+][OH^-] = 10^{-14}$ à 25°C. Par symétrie ($[H_3O^+] = [OH^-]$), on a $[H_3O^+]^2 = 10^{-14}$, donc $[H_3O^+] = 10^{-7}$ mol/L. **D''où** : pH de l''eau pure = 7 (neutre).');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Si $[\text{H}_3\text{O}^+] = 10^{-3}$ mol/L, alors $[\text{OH}^-]$ vaut :', '**Produit ionique de l''eau** à 25°C : $[H_3O^+][OH^-] = K_e = 10^{-14}$. Donc $[OH^-] = K_e / [H_3O^+] = 10^{-14}/10^{-3} = 10^{-11}$ mol/L. **Cohérence** : pH = 3 (acide), pOH = 11 (basique faible), et pH + pOH = 14.');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Si le pH d''une solution est 4, $[\text{H}_3\text{O}^+]$ vaut :', 'Définition : $\text{pH} = -\log_{10}[H_3O^+]$, donc $[H_3O^+] = 10^{-\text{pH}} = 10^{-4}$ mol/L. **Mémo** : « pH = exposant changé de signe ». Solution à pH = 4 = légèrement acide (jus de tomate, vinaigre dilué).');
SELECT public._patch_cp_sma2('sma_ph_definition', 'Si on dilue dix fois une solution acide forte initialement à pH = 3, le nouveau pH vaut environ :', 'Pour un **acide fort**, dilution × 10 → $[H_3O^+]$ divisée par 10 → pH augmente de 1. Donc pH passe de 3 à environ 4. **Limite** : à très grande dilution, pH tend vers 7 (eau pure) — l''autoprotolyse de l''eau prend le relais. Pour un acide faible, la relation est différente (le pH augmente moins).');
SELECT public._patch_cp_sma2('sma_primitives', '$\int_0^1 2x\,dx$ :', 'Primitive de $2x$ : $x^2$ (vérification : $(x^2)'' = 2x$ ✓). **Newton-Leibniz** : $\int_0^1 2x\,dx = [x^2]_0^1 = 1 - 0 = 1$. **Vérification géométrique** : $y = 2x$ entre 0 et 1 forme un triangle de base 1 et hauteur 2, aire = $\dfrac{1}{2} \times 1 \times 2 = 1$ ✓.');
SELECT public._patch_cp_sma2('sma_primitives', '$(x^2)\'' = ?$', '**Règle des puissances** : $(x^n)'' = n x^{n-1}$. Avec $n = 2$ : $(x^2)'' = 2x$. **Vérification par taux d''accroissement** : $\dfrac{(x+h)^2 - x^2}{h} = \dfrac{2xh + h^2}{h} = 2x + h \to 2x$ quand $h \to 0$ ✓.');
SELECT public._patch_cp_sma2('sma_primitives', '$(\sin x)\'' = ?$', '$(\sin x)'' = \cos x$. **Astuce mnémotechnique** : sin → cos (sans signe), cos → -sin (avec signe). Géométriquement : la pente de $\sin$ en 0 vaut 1 (= $\cos 0$), s''annule en $\pi/2$ (= $\cos(\pi/2) = 0$), devient $-1$ en $\pi$. Tout cohérent avec la courbe.');
SELECT public._patch_cp_sma2('sma_primitives', 'Primitive de $2x$ :', '$\int 2x\,dx = x^2 + C$. **Vérification** : $(x^2)'' = 2x$ ✓. **Erreur classique** : oublier la constante $C$ — toute primitive est définie à une constante près. Si la question demande **une** primitive (pas la), prendre $C = 0$ donne $x^2$.');
SELECT public._patch_cp_sma2('sma_primitives', 'Primitive de $1/x$ sur $]0,+\infty[$ :', '$(\ln x)'' = 1/x$ pour $x > 0$, donc $\int \dfrac{1}{x}\,dx = \ln x + C$ sur $]0, +\infty[$. **Sur $\mathbb{R}^*$** : la primitive est $\ln|x| + C$ (valeur absolue). **Cas particulier important** : $1/x$ n''admet pas de primitive sous forme polynomiale — c''est le logarithme qui prend le relais.');
SELECT public._patch_cp_sma2('sma_primitives', '$\int_0^\pi \sin x\,dx$ :', 'Primitive de $\sin x$ : $-\cos x$ (vérification : $(-\cos x)'' = \sin x$ ✓). **Newton-Leibniz** : $\int_0^\pi \sin x\,dx = [-\cos x]_0^\pi = -\cos\pi + \cos 0 = -(-1) + 1 = 2$. **Géométrique** : c''est l''aire d''une demi-arche de sinus, pas trivialement calculable sans intégration.');
SELECT public._patch_cp_sma2('sma_primitives', 'Pour intégrer $x \sin x$, le bon choix de $u$ dans l''IPP est :', '**Intégration par parties (IPP)** : $\int u\,v''\,dx = uv - \int u''v\,dx$. Stratégie LIATE : choisir $u$ qui se simplifie en se dérivant. Ici : $u = x$ (dérivée 1, plus simple), $v'' = \sin x$ ($v = -\cos x$). **Application** : $\int x\sin x\,dx = -x\cos x + \int \cos x\,dx = -x\cos x + \sin x + C$.');
SELECT public._patch_cp_sma2('sma_projectile_motion', 'Sur un objet en chute libre, la seule force est :', '**Chute libre** = mouvement sous l''effet du **seul poids** $\vec{P} = m\vec{g}$. On néglige les frottements de l''air (sinon ce n''est plus chute libre). Conséquence : accélération constante $\vec{a} = \vec{g}$ (vers le bas, $g \approx 9{,}81$ m/s²), indépendante de la masse — c''est l''expérience de Galilée.');
SELECT public._patch_cp_sma2('sma_projectile_motion', 'Sans frottement, le mouvement horizontal d''un projectile est :', 'Sans frottement, **aucune force horizontale** ne s''exerce sur le projectile (le poids est purement vertical). Donc $a_x = 0$ et **$v_x$ reste constant** — c''est un MRU horizontal. Le mouvement vertical, lui, est uniformément accéléré ($a_y = -g$). On parle de mouvement parabolique.');
SELECT public._patch_cp_sma2('sma_projectile_motion', 'À $t = 1$s, vitesse en chute libre depuis repos ($g = 10$ m/s²) :', 'Chute libre depuis repos : $v(t) = g t$ (intégration de $a = g$). À $t = 1$ s avec $g = 10$ m/s² : $v = 10$ m/s. **Cohérence** : à $t = 2$ s, $v = 20$ m/s ; à $t = 5$ s, $v = 50$ m/s. La vitesse augmente linéairement avec le temps.');
SELECT public._patch_cp_sma2('sma_projectile_motion', 'Sur le sommet de la trajectoire, $v_y$ vaut :', 'Au sommet de la trajectoire d''un projectile, la composante verticale **$v_y = 0$** : c''est le moment où le projectile arrête de monter et commence à redescendre. La composante horizontale $v_x$, elle, reste inchangée (pas de force horizontale). **Application** : pour atteindre la portée maximale, l''angle de tir optimal sans frottements est 45°.');
SELECT public._patch_cp_sma2('sma_qr_k', 'Pour augmenter le rendement, on peut :', 'Pour augmenter le rendement d''une réaction $aA + bB \rightleftharpoons cC + dD$, il faut **déplacer l''équilibre vers les produits** (loi de Le Chatelier). Méthodes : (1) **éliminer C ou D** au fur et à mesure (fait baisser $Q_r$, le système réagit dans le sens direct pour réajuster) ; (2) ajouter A ou B en excès ; (3) ajuster température si exo/endothermique.');
SELECT public._patch_cp_sma2('sma_qr_k', 'K dépend de :', 'La constante d''équilibre $K$ (à ne pas confondre avec $Q_r$) **ne dépend que de la température** pour une réaction donnée. Elle est indépendante des concentrations initiales, du volume, de la pression (en solution diluée), et des catalyseurs. Si T change, $K$ change selon la loi de Van''t Hoff. **À T fixée, $K$ est une constante**.');
SELECT public._patch_cp_sma2('sma_qr_k', 'K grand ⟹ équilibre :', '$K = \dfrac{[C]^c[D]^d}{[A]^a[B]^b}$ à l''équilibre. **K grand** signifie numérateur grand, dénominateur petit → **les produits dominent** à l''équilibre, la réaction est très avancée dans le sens direct (quasi-totale si $K \gg 10^4$). **K petit** : réactifs dominent, peu de réaction.');
SELECT public._patch_cp_sma2('sma_qr_k', '$K = 10$, à un moment $Q_r = 50$. Le système évolue :', '**Critère d''évolution** : si $Q_r > K$, trop de produits par rapport à l''équilibre → la réaction évolue dans le **sens inverse** (consomme C, D ; reforme A, B) jusqu''à ce que $Q_r$ baisse à $K$. Inversement, $Q_r < K$ → sens direct. Ici $Q_r = 50 > K = 10$, donc **sens inverse**.');
SELECT public._patch_cp_sma2('sma_rc_charge_discharge', 'Si $C = 100\,\mu F$ porte $q = 10^{-3}$ C, $u_C = ?$', 'Relation **charge-tension** d''un condensateur : $q = C u$, donc $u = q/C$. Application : $u = 10^{-3}/(100 \times 10^{-6}) = 10^{-3}/10^{-4} = 10$ V. **Unités** : C/F = V ✓ (puisque 1 F = 1 C/V).');
SELECT public._patch_cp_sma2('sma_rc_charge_discharge', 'À $t = \tau$, $u_C$ vaut environ :', 'En décharge d''un condensateur, $u_C(t) = E e^{-t/\tau}$. À $t = \tau$ : $u_C(\tau) = E e^{-1} \approx 0{,}37 E$ — il reste **37%** de la tension initiale (équivalent : 63% perdus). Mémo : $e^{-1} \approx 0{,}37$, $e^{-2} \approx 0{,}14$, $e^{-3} \approx 0{,}05$. À $5\tau$, plus de 99% perdus.');
SELECT public._patch_cp_sma2('sma_rc_charge_discharge', '$C = 100\,\mu F$, $u_C = 10$ V. $E_C = ?$', '**Énergie stockée dans un condensateur** : $E_C = \dfrac{1}{2} C u^2$. Application : $E_C = 0{,}5 \times 100 \times 10^{-6} \times 100 = 5 \times 10^{-3}$ J = 5 mJ. **Analogie** avec énergie cinétique $\frac{1}{2}mv^2$ : la charge joue le rôle d''une vitesse électrique.');
SELECT public._patch_cp_sma2('sma_rc_charge_discharge', 'À $t = \tau$, $u_C$ vaut environ :', 'En **charge** d''un condensateur, $u_C(t) = E(1 - e^{-t/\tau})$. À $t = \tau$ : $u_C(\tau) = E(1 - e^{-1}) \approx 0{,}63 E$ — chargé à **63%**. À $t = 5\tau$, chargé à plus de 99% — on considère le régime établi.');
SELECT public._patch_cp_sma2('sma_rc_charge_discharge', 'Si on double $R$, $\tau$ :', '**Constante de temps** RC : $\tau = RC$. Doubler $R$ → **double $\tau$** (charge/décharge plus lente). De même, doubler $C$ double aussi $\tau$. **Mémo** : $\tau$ proportionnel au produit. Pour réduire $\tau$ d''un facteur 2, on peut diminuer R ou C de moitié.');
SELECT public._patch_cp_sma2('sma_reaction_speed', 'Un catalyseur :', '**Définition d''un catalyseur** : substance qui **accélère une réaction sans être consommée** (régénérée à la fin). Il abaisse l''énergie d''activation, **n''affecte pas l''équilibre** (ni $K$ ni le rendement final), seulement la vitesse pour l''atteindre. Exemple : platine dans un pot catalytique, enzymes en biologie.');
SELECT public._patch_cp_sma2('sma_reaction_speed', 'Vitesse de réaction : unité SI ?', 'La **vitesse de réaction** est $v = -\dfrac{1}{\nu_A} \dfrac{d[A]}{dt}$ — variation de concentration par unité de temps. Unité SI : **mol·L⁻¹·s⁻¹** (concentration/temps). Souvent on utilise mol·L⁻¹·min⁻¹ en pratique pour des réactions plus lentes.');
SELECT public._patch_cp_sma2('sma_reaction_speed', 'La cinétique étudie :', 'La **cinétique chimique** étudie la **vitesse** des réactions chimiques (vs. la thermodynamique, qui étudie les états d''équilibre et les rendements). Questions cinétiques : combien de temps faut-il pour atteindre l''équilibre ? Quelle température/concentration accélère ? Quel mécanisme microscopique ?');
SELECT public._patch_cp_sma2('sma_reaction_speed', 'Pour une cinétique d\''ordre 1, $t_{1/2}$ dépend :', '**Cinétique d''ordre 1** : $-d[A]/dt = k[A]$, solution $[A](t) = [A]_0 e^{-kt}$. La demi-vie $t_{1/2} = \ln 2/k$ — **indépendante de la concentration initiale** (caractéristique unique de l''ordre 1). C''est pour cela qu''on parle de demi-vie en radioactivité (ordre 1) ou en pharmacocinétique.');
SELECT public._patch_cp_sma2('sma_reaction_speed', 'Augmenter la température :', 'Augmenter la **température** augmente l''énergie cinétique des molécules → plus de chocs, et plus de chocs **efficaces** (énergie > énergie d''activation). **Loi d''Arrhenius** : $k = A e^{-E_a/(RT)}$ — la constante de vitesse augmente exponentiellement avec T. Règle empirique : +10 °C ≈ vitesse × 2 à 4.');
SELECT public._patch_cp_sma2('sma_reversible_basics', 'Si $Q_r < K$ :', '**Critère d''évolution** : $Q_r$ représente l''état actuel, $K$ l''état d''équilibre. Si $Q_r < K$ : trop de réactifs → la réaction évolue dans le **sens direct** (consomme A, B ; produit C, D) jusqu''à ce que $Q_r$ remonte à $K$. C''est la loi d''évolution spontanée d''un système chimique.');
SELECT public._patch_cp_sma2('sma_reversible_basics', 'Une réaction réversible :', 'Une **réaction réversible** peut s''effectuer dans les deux sens : $aA + bB \rightleftharpoons cC + dD$. Notation : double flèche. À l''équilibre, les deux réactions (directe et inverse) ont **même vitesse** — l''équilibre est **dynamique** (les molécules continuent à réagir, mais les concentrations restent stables).');
SELECT public._patch_cp_sma2('sma_reversible_basics', 'Quand la réaction directe est aussi rapide que l\''inverse :', 'L''**équilibre dynamique** est atteint quand $v_{\text{directe}} = v_{\text{inverse}}$. Conséquence : les concentrations restent constantes au cours du temps — l''équilibre est **macroscopiquement stable** (mais dynamique au niveau microscopique). C''est le critère d''équilibre cinétique, équivalent à $Q_r = K$.');
SELECT public._patch_cp_sma2('sma_reversible_basics', 'À l''équilibre, les concentrations :', 'À l''équilibre chimique, les concentrations de tous les réactifs et produits **restent stables** au cours du temps (équilibre macroscopique). Au niveau microscopique, les réactions directe et inverse continuent à même vitesse — c''est un **équilibre dynamique**. La condition mathématique : $Q_r = K$.');
SELECT public._patch_cp_sma2('sma_rl_establishment', '$L = 0{,}1$ H, $di/dt = 5$ A/s. $u_L = ?$', '**Tension aux bornes d''une bobine** : $u_L = L\,di/dt$. Application : $u_L = 0{,}1 \times 5 = 0{,}5$ V. **Unités** : H × A/s = V ✓. **Sens conventionnel** : la bobine **s''oppose** à la variation de courant — la tension induite est en phase avec $di/dt$ par cette définition.');
SELECT public._patch_cp_sma2('sma_rl_establishment', 'À l''ouverture, le courant :', 'Lors de l''**ouverture du circuit RL**, la bobine **s''oppose à la variation brusque** du courant (loi de Lenz). Le courant ne tombe pas instantanément à 0 mais décroît exponentiellement : $i(t) = I_0 e^{-t/\tau}$ avec $\tau = L/R$. **Phénomène** : on peut observer une étincelle aux contacts (surtension inductive).');
SELECT public._patch_cp_sma2('sma_rl_establishment', '$L = 0{,}5$ H, $i = 2$ A. $E_L = ?$', '**Énergie stockée dans une bobine** : $E_L = \dfrac{1}{2} L i^2$. Application : $E_L = 0{,}5 \times 0{,}5 \times 2^2 = 0{,}5 \times 0{,}5 \times 4 = 1$ J. **Analogie mécanique** : $E_L$ joue le rôle de l''énergie cinétique $\frac{1}{2}mv^2$, le courant comme une vitesse, l''inductance comme une masse.');
SELECT public._patch_cp_sma2('sma_rl_establishment', 'À $t = \tau$, $i$ vaut environ :', 'Lors de l''**établissement du courant** dans un RL : $i(t) = I_0 (1 - e^{-t/\tau})$. À $t = \tau$ : $i(\tau) = I_0(1 - e^{-1}) \approx 0{,}63 I_0$ — le courant a atteint **63%** de sa valeur finale. À $5\tau$, plus de 99% — on considère que le régime permanent est établi.');
SELECT public._patch_cp_sma2('sma_rl_establishment', 'Si on double $L$, $\tau$ :', '**Constante de temps** d''un circuit RL : $\tau = L/R$. Doubler $L$ → **double $\tau$** (établissement plus lent). À l''inverse, doubler $R$ divise $\tau$ par 2. **Mémo** : grand $\tau$ = inertie magnétique forte = bobine large + résistance faible.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Pour qu''un RLC pseudo-périodique s''amortisse plus vite, il faut :', 'En régime **pseudo-périodique** (faiblement amorti), l''amplitude décroît selon $e^{-t/\tau}$ avec $\tau = 2L/R$. **Pour amortir plus vite**, il faut $\tau$ plus petit, donc **augmenter $R$** (ou diminuer $L$). Trop fort : on bascule en régime apériodique (sans oscillation), passant par un régime critique.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Si on **double** $L$ tout en gardant $C$, comment évolue la période propre $T_0$ ?', '**Période propre** $T_0 = 2\pi\sqrt{LC}$ — proportionnelle à $\sqrt{LC}$. Doubler $L$ multiplie $T_0$ par $\sqrt{2} \approx 1{,}41$. Pour doubler $T_0$, il faudrait quadrupler $L$. **Cohérence dimensionnelle** : T = $\sqrt{H \cdot F} = \sqrt{V s/A \cdot As/V} = \sqrt{s^2}$ = s ✓.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Si $R \to 0$ (très peu d\''amortissement), le régime devient :', 'Sans résistance ($R = 0$), l''oscillation est **sinusoïdale pure non amortie** de pulsation propre $\omega_0 = 1/\sqrt{LC}$ — c''est l''**oscillateur harmonique idéal LC**. L''énergie oscille entre la bobine ($\frac{1}{2}Li^2$) et le condensateur ($\frac{1}{2}Cu^2$) sans dissipation. **Cas réel** : $R \ne 0$ toujours, donc oscillations finissent par s''amortir.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Régime sans oscillation, retour rapide à zéro :', 'Le **régime critique** est exactement le seuil où l''oscillation disparaît : retour à zéro le plus rapide possible **sans dépassement** ni oscillation. Condition : $R = 2\sqrt{L/C}$. Au-delà : régime apériodique (lent). En deçà : pseudo-périodique (oscillant). Application : amortisseurs de voiture conçus en régime critique pour confort optimal.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'L''analogie mécanique RLC ↔ masse-ressort avec frottement : qu''est-ce qui correspond au coefficient de frottement $f$ ?', '**Analogie électromécanique** : $L \leftrightarrow m$ (inertie), $1/C \leftrightarrow k$ (raideur), **$R \leftrightarrow f$ (frottement)**, $i \leftrightarrow v$ (vitesse), $q \leftrightarrow x$ (position). Comme $f$ dissipe l''énergie cinétique en chaleur, $R$ dissipe l''énergie électrique par effet Joule. Cette analogie permet de transposer méthodes mécaniques aux circuits.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'L\''équation $L \ddot q + R \dot q + q/C = 0$ est :', '**EDO linéaire d''ordre 2 à coefficients constants, sans second membre (homogène/régime libre)**. Coefficients $L, R, 1/C$ tous constants. Forme canonique du RLC série en régime libre. **Solutions** dépendent du discriminant $\Delta = R^2 - 4L/C$ : $\Delta < 0$ pseudo-périodique, $\Delta = 0$ critique, $\Delta > 0$ apériodique.');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Une bobine $L = 0{,}1$ H. Si $di/dt = 4$ A/s, sa tension vaut :', 'Tension d''une bobine : $u_L = L\,di/dt = 0{,}1 \times 4 = 0{,}4$ V. **Unités** : H × A/s = V ✓. La bobine s''oppose à la variation : si le courant augmente, $u_L > 0$ ; s''il diminue, $u_L < 0$ (loi de Lenz).');
SELECT public._patch_cp_sma2('sma_rlc_regimes', 'Un condensateur de capacité $C = 10\,\mu F$ porte la charge $q = 5\times 10^{-5}$ C. Sa tension vaut :', '**Loi du condensateur** : $u = q/C$. Application : $u = 5 \times 10^{-5} / (10 \times 10^{-6}) = 5$ V. **Unités** : C/F = V ✓. À retenir : $\mu F \times V = \mu C$ — pratique pour estimations rapides.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Si $u_{n+1} = \frac{u_n + 6}{2}$ converge vers $L$, alors $L$ vaut :', '**Méthode du point fixe** : si $(u_n)$ converge vers $L$ et que $u_{n+1} = f(u_n)$ avec $f$ continue, alors $L = f(L)$. Ici : $L = (L+6)/2$, soit $2L = L + 6$, donc $L = 6$. **Vérification** : $f(6) = (6+6)/2 = 6$ ✓ — c''est bien un point fixe.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Une suite croissante et majorée :', '**Théorème de la convergence monotone** : toute suite croissante et majorée **converge** vers une limite finie (≤ majorant). De même, toute suite décroissante et minorée converge. C''est le théorème central pour démontrer la convergence des suites récurrentes — pas besoin de calculer la limite, l''existence suffit.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Soit $(u_n)$ définie par $u_n = 2n + 1$. Que vaut $u_3$ ?', 'Substitution directe dans la formule explicite : $u_3 = 2 \times 3 + 1 = 7$. **Pas besoin de calculer $u_0, u_1, u_2$** d''abord — la formule explicite donne directement le terme. C''est la suite arithmétique de premier terme $u_0 = 1$ et raison $r = 2$.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Soit $(v_n)$ définie par $v_0 = 1$ et $v_{n+1} = 3 v_n$. Que vaut $v_2$ ?', '**Suite récurrente géométrique** : $v_{n+1} = 3 v_n$, raison $q = 3$. Calcul terme à terme : $v_1 = 3 v_0 = 3$, puis $v_2 = 3 v_1 = 9$. **Vérification par formule explicite** : $v_n = v_0 \cdot q^n = 1 \cdot 3^n$, donc $v_2 = 9$ ✓.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Soit $(u_n)$ arithmétique, $u_0 = 7$, $u_5 = 22$. Quelle est la raison ?', '**Formule explicite** d''une suite arithmétique : $u_n = u_0 + n r$. Application : $u_5 = u_0 + 5r$, soit $22 = 7 + 5r$, donc $5r = 15$, donc $r = 3$. **Vérification** : $u_5 = 7 + 5 \times 3 = 22$ ✓.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Soit $(v_n)$ géométrique de raison $q = 2$, $v_0 = 5$. $v_3$ ?', '**Formule explicite** d''une suite géométrique : $v_n = v_0 \cdot q^n$. Application : $v_3 = 5 \cdot 2^3 = 5 \cdot 8 = 40$. **Vérification par récurrence** : $v_1 = 10, v_2 = 20, v_3 = 40$ ✓ — chaque terme double.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'Que vaut $\lim_{n\to+\infty} \left(\frac{1}{2}\right)^n$ ?', 'Suite géométrique de raison $q = 1/2$, donc $|q| < 1$. **Règle** : $|q| < 1 \Rightarrow q^n \to 0$. La suite tend vers 0 : $\lim (1/2)^n = 0$. **Intuition** : on divise par 2 à chaque étape, on devient infiniment petit. Décroissance exponentielle vers 0.');
SELECT public._patch_cp_sma2('sma_sequences_review', 'La suite $u_n = (-1)^n$ :', '$(-1)^n$ vaut alternativement 1 (si $n$ pair) et $-1$ (si $n$ impair). La suite **oscille** entre ces deux valeurs sans se stabiliser → **pas de limite**. **Cas général** : $q^n$ pour $q \le -1$ n''a pas de limite (oscillations divergentes pour $q < -1$, oscillations bornées pour $q = -1$).');
SELECT public._patch_cp_sma2('sma_sequences_review', '$\lim_{n\to+\infty} \dfrac{n^2 + 1}{n+5}$ vaut :', 'Quotient de polynômes : numérateur de **degré 2**, dénominateur de **degré 1**. Le numérateur l''emporte → **limite $+\infty$**. **Démonstration formelle** : factoriser $n^2$ haut, $n$ bas : $\dfrac{n^2(1 + 1/n^2)}{n(1 + 5/n)} = n \cdot \dfrac{1 + 1/n^2}{1 + 5/n} \to +\infty \cdot 1 = +\infty$.');
SELECT public._patch_cp_sma2('sma_titration_curve', 'Le saut brusque sur la courbe pH = f(V) localise :', 'Le **saut brusque de pH** sur la courbe de dosage signale le passage de l''excès d''acide (avant l''équivalence) à l''excès de base (après) — c''est l''**équivalence**, où les quantités stoechiométriques sont en présence. Le volume correspondant $V_{\text{éq}}$ permet de calculer la concentration inconnue.');
SELECT public._patch_cp_sma2('sma_titration_curve', 'Pour un dosage acide fort / base forte, le pH à l''équivalence vaut :', 'À l''équivalence d''un dosage **acide fort + base forte** (HCl + NaOH par exemple), il ne reste que le sel formé (NaCl) dans l''eau — sel **neutre** (ni acide ni basique). Donc **pH = 7** (à 25°C). **Indicateur adapté** : BBT (zone 6,0–7,6) ou phénolphtaléine (saut très net).');
SELECT public._patch_cp_sma2('sma_titration_curve', 'Pour un dosage acide faible / base forte, le pH d''équivalence est :', 'À l''équivalence d''un dosage **acide faible + base forte**, il reste la base conjuguée du faible ($A^-$) en solution. Cette base conjuguée donne un pH **basique** (> 7). Exemple : dosage acide acétique + NaOH → équivalence à pH ≈ 8,8. **Indicateur adapté** : phénolphtaléine (zone 8,2–10).');
SELECT public._patch_cp_sma2('sma_titration_curve', 'La méthode la plus fiable pour un saut peu marqué (acide très faible) est :', 'Pour un saut peu visible à l''œil, la méthode la plus fiable est la **méthode des dérivées** : tracer $dpH/dV$ qui présente un **maximum bien défini à l''équivalence** même quand le saut visuel est peu marqué. Méthode **quantitative**, plus précise que l''œil. Outil disponible sur la plupart des pH-mètres modernes.');
SELECT public._patch_cp_sma2('sma_titration_curve', 'Pour doser HCl par NaOH, l''indicateur le plus adapté est :', 'Acide fort + base forte → pH d''équivalence = 7. **BBT** (Bleu de Bromothymol, zone 6,0–7,6) est centré sur 7 — idéal. **Phénolphtaléine** (8,2–10) fonctionne aussi en pratique grâce au saut très brutal qui balaie sa zone de virage. **Hélianthine** (3,1–4,4) virerait trop tôt — inadaptée.');
SELECT public._patch_cp_sma2('sma_titration_curve', 'L''hélianthine est adaptée aux dosages où le pH d''équivalence vaut :', 'L''**hélianthine** a une zone de virage **3,1–4,4** — adaptée aux pH d''équivalence autour de 4. Cas typique : dosage **base faible + acide fort** (l''équivalence donne pH acide). Exemple : dosage NH₃ + HCl → équivalence à pH ≈ 5,1, hélianthine convient bien.');
SELECT public._patch_cp_sma2('sma_titration_curve', 'Si on dose 20 mL d''un acide à 0,1 mol/L par une base à 0,05 mol/L, le volume à l''équivalence vaut :', 'À l''équivalence : $C_a V_a = C_b V_{b,\text{éq}}$ (1:1 pour acide/base monovalents). Donc $V_{b,\text{éq}} = \dfrac{C_a V_a}{C_b} = \dfrac{0{,}1 \times 20}{0{,}05} = \dfrac{2}{0{,}05} = 40$ mL. **Cohérent** : la base est moitié moins concentrée, il en faut deux fois plus en volume.');
SELECT public._patch_cp_sma2('sma_vectors_3d', 'Si $\vec{u} \cdot \vec{v} = 0$ :', '**Critère d''orthogonalité** : $\vec{u} \cdot \vec{v} = 0 \iff \vec{u} \perp \vec{v}$ (vecteurs perpendiculaires) ou l''un des deux est nul. **Justification** : $\vec{u} \cdot \vec{v} = |\vec{u}||\vec{v}|\cos\theta$, qui s''annule ssi $\cos\theta = 0$, soit $\theta = \pi/2$ (vecteurs perpendiculaires).');
SELECT public._patch_cp_sma2('sma_vectors_3d', 'Vecteur normal au plan $2x + y - z = 5$ :', 'Pour un plan d''équation $ax + by + cz = d$, un **vecteur normal** est $\vec{n} = (a, b, c)$ — c''est-à-dire les **coefficients de $x, y, z$**. Ici : $\vec{n} = (2, 1, -1)$. Tout vecteur colinéaire à $\vec{n}$ est aussi normal au plan ($2\vec{n}$, $-\vec{n}$, etc.).');
SELECT public._patch_cp_sma2('sma_vectors_3d', '$d(O, x+y+z=3)$ :', '**Distance d''un point à un plan** : $d(M_0, \mathcal{P}) = \dfrac{|ax_0 + by_0 + cz_0 - d|}{\sqrt{a^2+b^2+c^2}}$. Ici $O = (0,0,0)$, plan $x+y+z = 3$ ($a=b=c=1, d=3$) : $d = \dfrac{|0+0+0-3|}{\sqrt{3}} = \dfrac{3}{\sqrt{3}} = \sqrt{3}$.');
SELECT public._patch_cp_sma2('sma_vectors_3d', '$\vec{AB}$ pour $A(1,2,3)$ et $B(4,6,3)$ :', '**Coordonnées du vecteur $\vec{AB}$** : $\vec{AB} = B - A = (4-1, 6-2, 3-3) = (3, 4, 0)$. **Norme** : $\|\vec{AB}\| = \sqrt{9 + 16 + 0} = 5$. **Direction** : dans le plan $z = 3$ (pas de variation en $z$).');
SELECT public._patch_cp_sma2('sma_vectors_3d', '$\vec{u} \wedge \vec{v}$ est :', '**Propriété fondamentale du produit vectoriel** : $\vec{u} \wedge \vec{v}$ est un vecteur **perpendiculaire à $\vec{u}$ et à $\vec{v}$**, de norme $|\vec{u}||\vec{v}|\sin\theta$, et de sens donné par la règle de la main droite. **Application** : trouver une normale à un plan défini par deux vecteurs, force de Laplace, moments cinétiques.');
SELECT public._patch_cp_sma2('sma_wave_basics', 'Une onde sonore est :', 'Une **onde sonore** est une onde **longitudinale** : les compressions et raréfactions du milieu (air, eau...) se font **dans la direction de propagation**. Contrairement aux ondes transversales (corde vibrante, lumière) où les oscillations sont perpendiculaires. **Vitesse** : ~340 m/s dans l''air à 20°C, ~1500 m/s dans l''eau, ~5000 m/s dans l''acier.');
SELECT public._patch_cp_sma2('sma_wave_basics', 'Si $y_A(t) = \sin(\omega t)$ et le retard est $\tau$, alors :', 'Une onde se propage avec un **retard temporel** $\tau$ entre la source A et un point M plus loin : $y_M(t) = y_A(t - \tau)$. Application : $y_M(t) = \sin(\omega(t - \tau)) = \sin(\omega t - \omega\tau)$ — l''onde reproduit le mouvement de A avec un décalage. $\tau = d/v$ où $d$ est la distance et $v$ la célérité.');
SELECT public._patch_cp_sma2('sma_wave_basics', 'Le son va plus vite dans :', 'Plus le milieu est **dense et rigide**, plus la **célérité du son est grande**. Eau (1500 m/s) > air (340 m/s) ; acier (5000 m/s) > eau. **Pas de son dans le vide** : il faut un milieu matériel pour propager les compressions/raréfactions. Différent de la lumière (onde EM, se propage dans le vide).');
SELECT public._patch_cp_sma2('sma_wave_basics', 'Une onde transporte :', 'Une onde transporte de l''**énergie** (et de l''information), pas de la **matière**. Le milieu vibre **sur place** (mouvement local des particules), mais l''énergie progresse à la célérité $v$. **Exemple** : un bouchon flottant sur l''eau monte et descend mais ne se déplace pas latéralement avec les vagues.');
SELECT public._patch_cp_sma2('sma_wave_basics', 'Une vague à la surface de l''eau est :', 'Une **vague de surface** combine mouvement vertical (montée/descente) et mouvement horizontal (avance/recul) — c''est une onde **mixte** (à la fois transversale et longitudinale). Les particules d''eau décrivent en réalité des **trajectoires circulaires** près de la surface, plus aplaties en profondeur.');

DROP FUNCTION public._patch_cp_sma2(TEXT, TEXT, TEXT);
DROP FUNCTION public._patch_tryit_sma2(TEXT, TEXT, TEXT, TEXT);

COMMIT;